import{_ as r,c as t,a2 as a,o as n}from"./chunks/framework.Bzjhwp8w.js";const g=JSON.parse('{"title":"超智能代理带来灾难性风险：科学家AI能否提供更安全的路径？","description":"","frontmatter":{},"headers":[],"relativePath":"scientist_AI/index.md","filePath":"scientist_AI/index.md"}'),e={name:"scientist_AI/index.md"};function o(p,s,i,u,d,c){return n(),t("div",null,s[0]||(s[0]=[a('<h1 id="超智能代理带来灾难性风险-科学家ai能否提供更安全的路径" tabindex="-1">超智能代理带来灾难性风险：科学家AI能否提供更安全的路径？ <a class="header-anchor" href="#超智能代理带来灾难性风险-科学家ai能否提供更安全的路径" aria-label="Permalink to &quot;超智能代理带来灾难性风险：科学家AI能否提供更安全的路径？&quot;">​</a></h1><h2 id="作者" tabindex="-1">作者 <a class="header-anchor" href="#作者" aria-label="Permalink to &quot;作者&quot;">​</a></h2><p><strong>Yoshua Bengio</strong><sup>1,2,*</sup>, <strong>Michael Cohen</strong><sup>3</sup>, <strong>Damiano Fornasier</strong><sup>1</sup>, <strong>Joumanna Ghosn</strong><sup>1</sup>, <strong>Pietro Greiner</strong><sup>1</sup>, <strong>Matt MacDermott</strong><sup>4,1</sup>, <strong>Søren Mindermann</strong><sup>1</sup>, <strong>Adam Oberman</strong><sup>1,5</sup>, <strong>Jesse Richardson</strong><sup>1</sup>, <strong>Oliver Richardson</strong><sup>1,2</sup>, <strong>Marc-Antoine Rondeau</strong><sup>1</sup>, <strong>Pierre-Luc St-Charles</strong><sup>1</sup>, <strong>David Williams-King</strong><sup>1</sup></p><h2 id="机构" tabindex="-1">机构 <a class="header-anchor" href="#机构" aria-label="Permalink to &quot;机构&quot;">​</a></h2><p><sup>1</sup> Mila — 魁北克AI研究所<br><sup>2</sup> 蒙特利尔大学<br><sup>3</sup> 加州大学伯克利分校<br><sup>4</sup> 帝国理工学院<br><sup>5</sup> 麦吉尔大学</p><p><sup>*</sup> 主要作者。其他作者按字母顺序排列。</p><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>主要的AI公司日益关注于构建通用的AI代理——这些系统可以自主地计划、行动，并在几乎所有人类能够执行的任务中追求目标。尽管这些系统的用处不可否认，如果不加控制的AI代理将对公共安全构成重大风险，尤其是其潜在的误用可能导致人类控制的不可逆损失。我们讨论了这些风险如何源自当前的AI训练方法。实际上，各种场景和实验都表明可能有AI代理从事人类操作者未指定且与人类利益，如自我保护相冲突的欺骗或追求目标行为。遵循预防原则，我们看到一种更安全但仍有用的替代当前以代理为主导的发展方向的强烈需求。</p><p>因此，我们建议进一步推进开发一种可信且在设计上安全的非代理AI系统，我们称之为科学家AI（Scientist AI）。此系统旨在通过观测解释世界，而非采取行动模仿或取悦人类。它包含一个生成理论以解释数据的世界模型和一个回答问题的推理机器。这两个组件都明确使用不确定性概念来减轻过度自信预测的风险。鉴于这些考虑，科学家AI可以帮助研究人员加速科学进步，包括AI安全。特别地，我们的系统可以作为对抗即使面对风险仍可能创建的AI代理的防护措施。最终，专注于非代理AI可能在享受AI创新带来的好处同时避免与现有路线相关的风险。我们希望这些论点能激励研究人员、开发者和政策制定者青睐这种更安全的路径。</p>',9)]))}const h=r(e,[["render",o]]);export{g as __pageData,h as default};
